ALTER TABLE subjects ADD COLUMN IF NOT EXISTS exam_year INTEGER NOT NULL DEFAULT 2027;
ALTER TABLE subjects ADD COLUMN IF NOT EXISTS published BOOLEAN NOT NULL DEFAULT TRUE;
ALTER TABLE subjects ADD COLUMN IF NOT EXISTS position INTEGER NOT NULL DEFAULT 0;
ALTER TABLE subjects ADD COLUMN IF NOT EXISTS source_version TEXT NOT NULL DEFAULT 'osnova-2027-draft';
ALTER TABLE subjects ADD COLUMN IF NOT EXISTS content_version INTEGER NOT NULL DEFAULT 1;
ALTER TABLE subjects ADD COLUMN IF NOT EXISTS updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP;
CREATE TABLE IF NOT EXISTS sections (id BIGSERIAL PRIMARY KEY,subject_id BIGINT NOT NULL REFERENCES subjects(id) ON DELETE CASCADE,slug TEXT NOT NULL,title TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',position INTEGER NOT NULL DEFAULT 0,published BOOLEAN NOT NULL DEFAULT TRUE,exam_year INTEGER NOT NULL DEFAULT 2027,source_version TEXT NOT NULL DEFAULT 'osnova-2027-draft',content_version INTEGER NOT NULL DEFAULT 1,updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(subject_id,slug));
CREATE TABLE IF NOT EXISTS lessons (id BIGSERIAL PRIMARY KEY,topic_id BIGINT NOT NULL REFERENCES topics(id) ON DELETE CASCADE,slug TEXT NOT NULL,title TEXT NOT NULL,summary TEXT NOT NULL DEFAULT '',estimated_minutes INTEGER NOT NULL DEFAULT 15,difficulty TEXT NOT NULL DEFAULT 'base',exam_year INTEGER NOT NULL DEFAULT 2027,published BOOLEAN NOT NULL DEFAULT TRUE,position INTEGER NOT NULL DEFAULT 0,source_version TEXT NOT NULL DEFAULT 'osnova-2027-draft',content_version INTEGER NOT NULL DEFAULT 1,updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(topic_id,slug));
CREATE TABLE IF NOT EXISTS lesson_blocks (id BIGSERIAL PRIMARY KEY,lesson_id BIGINT NOT NULL REFERENCES lessons(id) ON DELETE CASCADE,type TEXT NOT NULL CHECK(type IN ('text','heading','definition','remember','important','example','exam_example','exam_trap','formula','reaction','table','list','image','diagram','comparison','algorithm','note','quiz','summary')),content_json JSONB NOT NULL DEFAULT '{}',position INTEGER NOT NULL DEFAULT 0,UNIQUE(lesson_id,position));
CREATE TABLE IF NOT EXISTS content_sources (id BIGSERIAL PRIMARY KEY,slug TEXT NOT NULL UNIQUE,title TEXT NOT NULL,source_type TEXT NOT NULL,source_version TEXT NOT NULL,exam_year INTEGER NOT NULL DEFAULT 2027,url TEXT,updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
ALTER TABLE topics ADD COLUMN IF NOT EXISTS section_id BIGINT REFERENCES sections(id) ON DELETE SET NULL;
ALTER TABLE topics ADD COLUMN IF NOT EXISTS exam_year INTEGER NOT NULL DEFAULT 2027; ALTER TABLE topics ADD COLUMN IF NOT EXISTS source_version TEXT NOT NULL DEFAULT 'osnova-2027-draft'; ALTER TABLE topics ADD COLUMN IF NOT EXISTS content_version INTEGER NOT NULL DEFAULT 1; ALTER TABLE topics ADD COLUMN IF NOT EXISTS updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP;
ALTER TABLE questions ADD COLUMN IF NOT EXISTS subject_id BIGINT REFERENCES subjects(id) ON DELETE CASCADE; ALTER TABLE questions ADD COLUMN IF NOT EXISTS lesson_id BIGINT REFERENCES lessons(id) ON DELETE SET NULL; ALTER TABLE questions ADD COLUMN IF NOT EXISTS external_key TEXT; ALTER TABLE questions ADD COLUMN IF NOT EXISTS question_type TEXT NOT NULL DEFAULT 'single_choice'; ALTER TABLE questions ADD COLUMN IF NOT EXISTS answer_data_json JSONB NOT NULL DEFAULT '{}'; ALTER TABLE questions ADD COLUMN IF NOT EXISTS explanation_json JSONB NOT NULL DEFAULT '{}'; ALTER TABLE questions ADD COLUMN IF NOT EXISTS source_type TEXT NOT NULL DEFAULT 'original'; ALTER TABLE questions ADD COLUMN IF NOT EXISTS exam_year INTEGER NOT NULL DEFAULT 2027; ALTER TABLE questions ADD COLUMN IF NOT EXISTS published BOOLEAN NOT NULL DEFAULT TRUE;
ALTER TABLE lesson_progress ADD COLUMN IF NOT EXISTS reading_progress INTEGER NOT NULL DEFAULT 0 CHECK(reading_progress BETWEEN 0 AND 100); ALTER TABLE lesson_progress ADD COLUMN IF NOT EXISTS last_opened_at TIMESTAMPTZ;
ALTER TABLE lesson_progress DROP CONSTRAINT IF EXISTS lesson_progress_lesson_id_fkey;
ALTER TABLE lesson_progress ADD CONSTRAINT lesson_progress_lesson_id_fkey FOREIGN KEY(lesson_id) REFERENCES lessons(id) ON DELETE CASCADE NOT VALID;
CREATE UNIQUE INDEX IF NOT EXISTS idx_questions_external_key ON questions(external_key); CREATE INDEX IF NOT EXISTS idx_sections_subject ON sections(subject_id,published,position); CREATE INDEX IF NOT EXISTS idx_topics_section ON topics(section_id,published,position); CREATE INDEX IF NOT EXISTS idx_lessons_topic ON lessons(topic_id,published,position); CREATE INDEX IF NOT EXISTS idx_lesson_blocks_lesson ON lesson_blocks(lesson_id,position);
UPDATE questions q SET subject_id=t.subject_id FROM topics t WHERE q.topic_id=t.id AND q.subject_id IS NULL;
